declare
  S jsonb := $slreg${"schema":"edgedesk_research_registration_v1","model_key":"NBA-ROLE-SHIFT","name":"NBA role shift — teammates' volume props when a rotation player is out","version":"0.1","status":"EXPERIMENTAL","provenance":"T3","provenance_label":"EdgeDesk research","sport":"NBA","registered_at":"2026-10-26","hypothesis":"When a top-8 rotation player is ruled OUT or DOUBTFUL, the market under-adjusts his teammates' volume props (rebounds, assists, 3-pointers made, points + rebounds + assists). An injury-conditioned regime, the existing props model fed with each teammate's minutes and per-minute rates from games without the absent player (shrunk toward the full-roster numbers), prices them closer to the close, so flags where its fair probability beats the posted price by 2.5 pp or more show positive CLV.","objective":"Measure whether injury-conditioned fair lines anticipate the market's adjustment, graded against the closing price at the same book and line, with the actual stat stored beside every grade. Research only: no flag is a recommendation.","primary_metric":"Mean CLV in percentage points over graded role-shift flags, CLV = the closing Shin no-vig probability of the flag's side at the same book and the same line minus the flag's cost (1 / decimal price, vig included), with its game-clustered 95% bootstrap interval. The actual stat and the over/under/push/void outcome are stored and reported, not the criterion.","unit":"One flag: one teammate, one market, one side at one posted line, one book. Clusters: the game (event_id).","baseline":"The default props model (nba/props/build_props.js, the previous-game rotation) and the market itself: no edge means mean CLV at most 0.","training_window":"None fitted for the regime: the props model is the existing one (trained on the four seasons before the current); the regime's splits use this season and last, as of each trigger.","validation_window":"None. There is no tuning step.","holdout_window":"Every role-shift flag from the first one onward. Evaluated at 200 graded flags and every 100 after; the repeated looks are disclosed.","machine":{"window_dates":{"training":null,"validation":null,"holdout":["2026-11-01",null]},"window_note":"[from, to): open-ended; the flag table is append-only","minimum_sample":200,"version":"0.1","status":"EXPERIMENTAL","provenance":"T3"},"minimum_sample":{"graded_flags":200,"note":"Below 200 graded flags the record is descriptive. Every flag counts, losses included."},"promotion_criteria":{"decision_rule":"eligible = true only if BOTH criteria hold on the graded flags at the time of evaluation. A criterion that cannot be evaluated is not met. Eligibility does not promote the model: a person promotes it to VALIDATED through a validation report. Software tests passing is never evidence for any criterion.","criteria":[{"id":"C1_SAMPLE","rule":"At least 200 graded flags (close_status = 'graded'). Flags with no usable close are counted and reported (the no-close count and rate), never graded and never counted toward the 200."},{"id":"C2_CLV_LOWER_BOUND","rule":"The lower end of the two-sided 95% percentile interval of the mean CLV (pp, flag-weighted) is above zero. The interval is a cluster bootstrap that resamples whole GAMES (event_id) with replacement: 2,000 resamples, mulberry32 seeded 20261026 (lib/edgedesk_sharp_lag.js clusterBootstrap), because flags in one game share its news and its close and are not independent."}],"family_correction":"Both are required (an intersection test); neither is reported as a pass on its own."},"forking_paths":{"candidates_tried":[{"version":"0.1","gap_pp":2.5,"trigger":"top-8 rotation player to OUT or DOUBTFUL","splits":"game-level primary, stints as the cross-check","shrinkage_games":10,"three_pct_prior_attempts":100,"evaluated_against_outcomes":false}],"alternatives_considered_not_tried":["the props model's own learned absence feature (miss_proj) instead of with/without splits","stint-level splits as the primary","QUESTIONABLE as a trigger","modelling 3-point attempts markets (books post made)"],"choice_and_reason":"The owner's specification: game-level splits primary (every stat exists per game; rebounds do not exist per stint), stints as the cross-check, 3-pointers made as modelled attempts times the shrunk 3P%, 2.5 pp.","data_already_seen":"No NBA prop price has ever been captured (the gateway's NBA row is disabled), so no role-shift flag has been computed or graded.","comparisons_made":0,"stopping_rule":"No stopping: the record runs on. Eligibility is evaluated at 200 graded flags and every 100 after."},"spec":{"trigger":"nba_injury_sync records a top-8 rotation player (reference rotation minutes, nba/roster_inputs.json) moving to OUT or DOUBTFUL","splits":"per teammate: minutes, usage (FGA + 0.44 FTA + TOV), FGA, 3PA, REB, AST, PTS per game in games WITHOUT the absent player vs WITH him, this season and last; shrunk = (n_without x without + k x with) / (n_without + k), k = 10 games; stints (on-court minutes, FGA, 3PA, assists) as the cross-check, reported beside, never overriding","regime":"the existing props model's prediction with minutes and per-minute rates from the shrunk splits (the default model and its output unchanged); 3-pointers made = modelled 3PA x the player's 3P% shrunk toward the league rate with 100 attempts","prices":"one nba_role_props request per game (player_rebounds, player_assists, player_threes, player_points_rebounds_assists; ten books, one region-equivalent, <= 4 credits), stored for the 3-4 teammates with the largest minutes or usage change","flag":"regime P(side at the posted line) - 1 / posted decimal >= 2.5 pp, at the first book posting the line in the order draftkings, fanduel, betmgm, williamhill_us, espnbet, betrivers, fanatics, hardrockbet, betonlineag, pinnacle; never the absent player's own unders","grade":"close = the same book's last two-way price at the same line at or before the tip, at most 90 minutes before it (else no close); CLV = closing Shin no-vig P(side) - flag cost; actual = the player's stat (void if he did not play)","code":"nba/props/role_shift.js; lib/edgedesk_sharp_lag.js; supabase/functions/sharp_lag","known_limitations":["the scenarios are built ahead, one per top-8 rotation player, in the 3-hourly NBA build and switched on when the report lands, so their inputs can be up to 3 hours old; a build more than 24 hours old switches nothing on","per-stint rebounds are not in the play-by-play stints","sample sizes without a player can be small: shrinkage is fixed, not fitted","a line that moves is graded only if the same line closes at the same book"]},"result":null,"content_sha256":"ffae4707bf0a6452ea147862cf1808acfcd3d8513ef0c092726a5a7188a211ee"}$slreg$::jsonb;
  m regclass := 'public.research_models';
  v regclass := 'public.research_model_versions';
  mv jsonb; vv jsonb; mach jsonb := S -> 'machine';
  kcol text; ncol text; refcol text; fkcol text; vcol text; vid text; c text; ref text; vref text; have boolean;
  pairs text[][] := array[
    array['training_window', 'train_window', 'training_period', 'training'],
    array['validation_window', 'valid_window', 'validation_period', 'validation'],
    array['holdout_window', 'holdout_period', 'holdout', 'test_window']];
  wkeys text[] := array['training', 'validation', 'holdout'];
  i int;
begin
  kcol := pg_temp.edr_has(m, array['model_key', 'key', 'model_name', 'model', 'slug', 'code', 'name']);
  if kcol is null then raise exception 'research registry: research_models has no key column (model_key, key, model_name, model, slug, code or name) — nothing was registered'; end if;
  select a.attname::text, ra.attname::text into fkcol, refcol
    from pg_constraint k
    join pg_attribute a on a.attrelid = k.conrelid and a.attnum = k.conkey[1]
    join pg_attribute ra on ra.attrelid = k.confrelid and ra.attnum = k.confkey[1]
   where k.contype = 'f' and k.conrelid = v and k.confrelid = m limit 1;
  if fkcol is null then
    fkcol := pg_temp.edr_has(v, array['model_key', 'model_id', 'research_model_id', 'model']);
    refcol := case when fkcol in ('model_id', 'research_model_id') then pg_temp.edr_has(m, array['id', 'model_id']) else kcol end;
  end if;
  if fkcol is null or refcol is null then raise exception 'research registry: cannot tell how research_model_versions points at research_models — nothing was registered'; end if;
  vcol := pg_temp.edr_has(v, array['version', 'model_version', 'version_label', 'semver', 'label']);
  vid := pg_temp.edr_has(v, array['id', 'version_id', 'model_version_id']);

  execute format('select %I::text from %s where %I::text = $1 limit 1', refcol, m, kcol) into ref using S ->> 'model_key';
  if ref is null then
    mv := jsonb_build_object(kcol, S ->> 'model_key');
    ncol := pg_temp.edr_has(m, array['name', 'title', 'display_name', 'label']);
    if ncol is not null and ncol <> kcol then mv := mv || jsonb_build_object(ncol, S ->> 'name'); end if;
    foreach c in array array['title', 'display_name'] loop
      if c <> kcol and pg_temp.edr_has(m, array[c]) is not null and not (mv ? c) then mv := mv || jsonb_build_object(c, S ->> 'name'); end if;
    end loop;
    c := pg_temp.edr_has(m, array['sport', 'league']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'sport'); end if;
    c := pg_temp.edr_has(m, array['status', 'model_status', 'maturity']); if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['experimental'])); end if;
    c := pg_temp.edr_has(m, array['provenance', 'evidence_provenance', 'tier', 'evidence_tier']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['t3', 'research_model', 'research', 'model'])); end if;
    c := pg_temp.edr_has(m, array['objective', 'goal']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'objective'); end if;
    c := pg_temp.edr_has(m, array['hypothesis']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['description', 'summary']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['family', 'category', 'module', 'domain']); if c is not null then mv := mv || jsonb_build_object(c, 'sharp_lag'); end if;
    c := pg_temp.edr_has(m, array['owner', 'created_by', 'registered_by']); if c is not null then mv := mv || jsonb_build_object(c, (S ->> 'registered_at') || ' preregistration (EdgeDesk research)'); end if;
    c := pg_temp.edr_has(m, array['metadata', 'meta', 'spec', 'details', 'config']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_val(m, c, null, S, null)); end if;
    ref := pg_temp.edr_insert(m, mv, refcol);
    raise notice 'research registry: % registered', S ->> 'model_key';
  else
    raise notice 'research registry: % was already registered and is left as it is', S ->> 'model_key';
  end if;

  if vcol is not null then
    execute format('select exists (select 1 from %s where %I::text = $1 and %I::text = $2)', v, fkcol, vcol) into have using ref, S ->> 'version';
  else
    execute format('select exists (select 1 from %s where %I::text = $1)', v, fkcol) into have using ref;
  end if;
  if not have then
    vv := jsonb_build_object(fkcol, ref);
    if vcol is not null then vv := vv || jsonb_build_object(vcol, S ->> 'version'); end if;
    c := pg_temp.edr_has(v, array['status', 'model_status', 'maturity']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['experimental'])); end if;
    c := pg_temp.edr_has(v, array['provenance', 'evidence_provenance', 'tier']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['t3', 'research_model', 'research', 'model'])); end if;
    for i in 1 .. 3 loop
      c := pg_temp.edr_has(v, pairs[i:i][1:4]::text[]);
      if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> (wkeys[i] || '_window'),
        jsonb_build_object('from', mach -> 'window_dates' -> wkeys[i] -> 0, 'to', mach -> 'window_dates' -> wkeys[i] -> 1, 'description', S ->> (wkeys[i] || '_window')),
        mach -> 'window_dates' -> wkeys[i])); end if;
    end loop;
    c := pg_temp.edr_has(v, array['objective', 'goal']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'objective', null, null)); end if;
    c := pg_temp.edr_has(v, array['hypothesis']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'hypothesis', null, null)); end if;
    c := pg_temp.edr_has(v, array['min_sample', 'minimum_sample', 'min_n', 'sample_target']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, (S -> 'minimum_sample')::text,
      case when pg_temp.edr_typ(v, c) in ('jsonb', 'json') then S -> 'minimum_sample' else mach -> 'minimum_sample' end, null)); end if;
    c := pg_temp.edr_has(v, array['success_metric', 'primary_metric', 'metric']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'primary_metric', null, null)); end if;
    c := pg_temp.edr_has(v, array['promotion_criteria', 'decision_rule', 'criteria', 'success_criteria']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S -> 'promotion_criteria' ->> 'decision_rule', S -> 'promotion_criteria', null)); end if;
    c := pg_temp.edr_has(v, array['forking_paths', 'forking_paths_disclosure', 'disclosure', 'garden_of_forking_paths']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'forking_paths', null)); end if;
    c := pg_temp.edr_has(v, array['spec', 'metadata', 'meta', 'params', 'config', 'details', 'definition', 'protocol']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'spec' || jsonb_build_object('content_sha256', S ->> 'content_sha256', 'registration', 'research/sharp_lag/registration_role_shift.json'), null)); end if;
    c := pg_temp.edr_has(v, array['notes', 'description']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c,
      'Preregistered ' || (S ->> 'registered_at') || ': research/sharp_lag/registration_role_shift.json sha256 ' || (S ->> 'content_sha256') || '. No result until a validation report writes one.', null, null)); end if;
    perform pg_temp.edr_insert(v, vv, fkcol);
  end if;

  -- the version row every stored projection must name
  if vid is not null and vcol is not null then
    execute format('select %I::text from %s where %I::text = $1 and %I::text = $2 limit 1', vid, v, fkcol, vcol) into vref using ref, S ->> 'version';
  end if;
  vref := coalesce(vref, ref || ':' || (S ->> 'version'));
  insert into public.sharp_lag_config (key, value, note) values
    ('registry_ref:' || (S ->> 'model_key'), vref, 'research_model_versions row (as text) every grade of this model must name; written only by supabase/sharp_lag_registry.sql'),
    ('registry_sha256:' || (S ->> 'model_key'), S ->> 'content_sha256', 'research/sharp_lag/registration_role_shift.json')
  on conflict (key) do update set value = excluded.value, note = excluded.note, updated_at = now()
    where public.sharp_lag_config.value is distinct from excluded.value;
end $reg$;

commit;

-- THE REPORT: each model as research_model_current reads it, and the link the grader needs. Every row should say ok.
create or replace function pg_temp.slr_report() returns table (piece text, state text)
language plpgsql as $f$
declare j jsonb; s text; p text; k text; n int := 0;
begin
  foreach k in array array['SHARP-LAG', 'NBA-ROLE-SHIFT'] loop
    n := n + 1;
    j := null;
    if to_regclass('public.research_model_current') is not null then
      execute 'select to_jsonb(r) from public.research_model_current r where lower(coalesce(to_jsonb(r) ->> ''model_key'', to_jsonb(r) ->> ''key'', to_jsonb(r) ->> ''model_name'', to_jsonb(r) ->> ''model'', to_jsonb(r) ->> ''name'')) = lower($1) limit 1'
        into j using k;
    end if;
    s := lower(coalesce(j ->> 'status', j ->> 'model_status', j ->> 'maturity', ''));
    p := coalesce(j ->> 'passed', 'null');
    piece := n || 'a ' || k || ' is EXPERIMENTAL with no result';
    state := case when to_regclass('public.research_model_current') is null then 'CHECK THIS: research_model_current is not in this database'
                  when j is null then 'CHECK THIS: not in research_model_current'
                  when s <> 'experimental' then 'CHECK THIS: status reads ' || s
                  when p = 'true' then 'CHECK THIS: a result row shows passed = true'
                  else 'ok' end;
    return next;
    piece := n || 'b the grader may grade ' || k || ' (its registry link is in sharp_lag_config)';
    state := case when exists (select 1 from public.sharp_lag_config where key = 'registry_ref:' || k) then 'ok' else 'CHECK THIS' end;
    return next;
  end loop;
end $f$;
select * from pg_temp.slr_report();
